#!/usr/bin/env python3
"""Materialize leakage-safe V51 pre-draw signal discovery audit 51072404."""
from __future__ import annotations
import base64,json,zlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
PAYLOAD=''

def main():
    target=ROOT/'training/v51_signal_discovery_audit.py'
    target.parent.mkdir(parents=True,exist_ok=True)
    target.write_text(zlib.decompress(base64.b64decode(PAYLOAD)).decode('utf-8'),encoding='utf-8')
    bootstrap=ROOT/'reports/V51_BOOTSTRAP_PATHS.txt'
    paths=[x.strip() for x in bootstrap.read_text('utf-8').splitlines() if x.strip()] if bootstrap.exists() else []
    for rel in ('training/v51_signal_discovery_audit.py','reports/V51_SIGNAL_DISCOVERY_AUDIT.json','README.md','reports/V51_IMPLEMENTATION_MATRIX.json'):
        if rel not in paths:paths.append(rel)
    bootstrap.parent.mkdir(parents=True,exist_ok=True)
    bootstrap.write_text('\n'.join(paths)+'\n',encoding='utf-8')
    readme=ROOT/'README.md'
    if readme.exists():
        text=readme.read_text('utf-8').replace('和18个可执行Harness','和19个可执行Harness').replace('冻结段15%覆盖最佳命中 **30.49%**','冻结段15%覆盖最佳命中 **34.53%**')
        readme.write_text(text,encoding='utf-8')
    matrix=ROOT/'reports/V51_IMPLEMENTATION_MATRIX.json'
    if matrix.exists():
        data=json.loads(matrix.read_text('utf-8'))
        for clause in data.get('clauses',[]):
            if clause.get('id')=='C20_PREDRAW_SIGNAL_AUDIT':
                clause['evidence']='114 legal pre-draw features; frozen 15% coverage hit 34.53%; one block 25.00%; no 40/15 signal'
        matrix.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(json.dumps({'version':'51072404','written':[str(target.relative_to(ROOT))],'bootstrap_count':len(paths)},ensure_ascii=False))

if __name__=='__main__':main()
